export interface IProductCartStatusViewModel {

    id: number;
    cartId: number;
    productId: number;
    productName: string;
    statusCode: number;
    description: string;
    price: number;
}

export class ProductCartStatusViewModel implements IProductCartStatusViewModel {

    id: number;
    cartId: number;
    productId: number;
    productName: string;
    statusCode: number;
    description: string;
    price: number;

    constructor(
        id: number,
        cartId: number,
        productId: number,
        productName: string,
        statusCode: number,
        description: string,
        price: number
    ) {
        this.id = id;
        this.productId = productId;
        this.productName = productName;
        this.cartId = cartId;
        this.statusCode = statusCode;
        this.description = description;
        this.price = price;
    }
}

