export class ProductCartModel implements IProductCartModel {

    id: number;
    isDelete: boolean;
    sellerId: number;
    isSeen: boolean;
    lastEmailSend: Date;
    name: string;
    designTitle: string;
    weight: number;
    price: number;
    offPrice: number;
    seller: ISellerModel;
    count: number;
    designId: number;
    sendRefId: string;
    description: string;
    statusCode: number;
    defaultSendPrice: number;
    defaultPriceEachKg: number;
    orderSendTypeId: number;
    cartId: number;
    productId: number;
    extraDeliveryPrice: number;
    hasDiscountLargeOrder: boolean;
    hasDiscountForEachOrder: boolean;
    discountPrice: number;
    maxDiscountPrice: number;
    discountPercent: number;
    maxDiscountPercent: number;
    discountOrderCount: number;
    hasFreeSend: boolean;

    email: string;
    productName: string;
    productCount: number;
    isOffPrice: boolean;
    offCode: string;
    offCodePercent: number;
    offCodePrice: number;
    offCodeId: number;
    sendTime: number;
    guaranteeDescription: string;
    referableDescription: string;
    isCorrupt: boolean;
    referable: boolean;
    consumption: boolean;
    hasGuarantee: boolean;
    isUsed: boolean;
    isFreeSend: boolean;
    isWholesale: boolean;
    portionPercent: number;
    portionPrice: number;
    hasFreeSendPrediction: boolean;
    freeSendPredictionPrice: number;
    minBikeDeliveryPrice: number;
    bikeDeliveryPriceEachKg: number;
    minTipaxPrice: number;
    tipaxPriceEachKg: number;
    minPostPrice: number;
    postPriceEachKg: number;
    minSpecialPostPrice: number;
    specialPostPriceEachKg: number;
    minBurberryPrice: number;
    burberryPriceEachKg: number;
    payAgain: IPayAgainViewModel[];

    constructor(
        productId: number,
        orderSendTypeId: number,
        count: number,
        weight: number,
        designId?: number,
        id?: number,
        name?: string,
        price?: number,
        offPrice?: number,
        seller?: ISellerModel,
        sendRefId?: string,
        description?: string,
        statusCode?: number,
        defaultSendPrice?: number,
        defaultPriceEachKg?: number,
        cartId?: number,
        extraDeliveryPrice?: number,
        hasFreeSend?: boolean
    ) {
        this.hasFreeSend = hasFreeSend;
        this.productId = productId;
        this.extraDeliveryPrice = extraDeliveryPrice ? extraDeliveryPrice : 0;
        this.orderSendTypeId = orderSendTypeId;
        this.count = count;
        this.weight = weight;
        this.designId = designId;
        this.id = id;
        this.name = name;
        this.price = price;
        this.offPrice = offPrice;
        this.seller = seller;
        this.sendRefId = sendRefId;
        this.description = description;
        this.statusCode = statusCode;
        this.defaultSendPrice = defaultSendPrice;
        this.defaultPriceEachKg = defaultPriceEachKg;
        this.cartId = cartId;
    }
}
