  GetCategory(ids: number[]): string {

    const output: string[] = [];

    ids.forEach(id => {

      GResponse.ProductCategory.forEach(c => {

        if (id === c.productCategoryId) {
          if (output.length !== 0) {
            output.push('/');
          }
          output.push(c.title);
        }
      });
    });

    return output.toString();
  }

